import { describe, it, expect } from "vitest";
import dayjs from "dayjs";
import timezone from "dayjs/plugin/timezone";
import utc from "dayjs/plugin/utc";
import { ACTION, STATE, reducer, createInitialState, } from "../stateMachine/dateRangePickerState";
dayjs.extend(utc);
dayjs.extend(timezone);
describe("dateRangePickerState", () => {
    const timezone = "UTC";
    const now = dayjs().tz(timezone).millisecond(0);
    const tests = [
        {
            action: { type: "UNKNOWN" },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: false,
                now,
                state: STATE.CUSTOM,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: false,
                now,
                state: STATE.CUSTOM,
            },
            title: "Unknown action returns unchanged state",
        },
        // CUSTOM state tests
        {
            action: { type: ACTION.CHANGE_TAB },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: false,
                now,
                state: STATE.CUSTOM,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: false,
                now,
                state: STATE.PRESET,
            },
            title: "CHANGE_TAB from CUSTOM moves to PRESET state",
        },
        {
            action: {
                newValue: [dayjs("2023-01-01"), dayjs("2023-01-07")],
                timezone,
                type: ACTION.CHANGE_CURRENT_VALUE,
            },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: false,
                now,
                state: STATE.CUSTOM,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-01-01"), dayjs("2023-01-07")],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: true,
                now: expect.any(Object),
                state: STATE.CUSTOM,
            },
            title: "CHANGE_CURRENT_VALUE in CUSTOM updates custom value and sets isDirty",
        },
        {
            action: {
                newValue: [dayjs("2023-01-01"), null],
                timezone,
                type: ACTION.SET_END_TO_NOW,
            },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-01-01"), dayjs("2023-01-07")],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: true,
                now,
                state: STATE.CUSTOM,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-01-01"), expect.any(Object)],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: true,
                now: expect.any(Object),
                state: STATE.CUSTOM,
            },
            title: "SET_END_TO_NOW in CUSTOM sets end date to current time",
        },
        {
            action: { type: ACTION.SUBMIT },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-01-01"), dayjs("2023-01-07")],
                currentTimeFrameValue: { timeFrame: "last-7-days" },
                isDirty: true,
                now,
                state: STATE.CUSTOM,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-01-01"), dayjs("2023-01-07")],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: false,
                now,
                state: STATE.CUSTOM,
            },
            title: "SUBMIT in CUSTOM clears timeFrame value",
        },
        {
            action: {
                initialValue: {
                    from: dayjs("2023-01-01").valueOf(),
                    to: dayjs("2023-01-07").valueOf(),
                },
                timezone,
                type: ACTION.RESET,
            },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-02-01"), dayjs("2023-02-07")],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: true,
                now,
                state: STATE.CUSTOM,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [expect.any(Object), expect.any(Object)],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: true,
                now,
                state: STATE.CUSTOM,
            },
            title: "RESET in CUSTOM resets to initial value",
        },
        {
            action: {
                initialValue: {
                    from: dayjs("2023-01-01").valueOf(),
                    to: dayjs("2023-01-07").valueOf(),
                },
                timezone,
                type: ACTION.CANCEL,
            },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-02-01"), dayjs("2023-02-07")],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: true,
                now,
                state: STATE.CUSTOM,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [expect.any(Object), expect.any(Object)],
                currentTimeFrameValue: { timeFrame: "" },
                isDirty: false,
                now: expect.any(Object),
                state: STATE.CUSTOM,
            },
            title: "CANCEL in CUSTOM returns to initial state",
        },
        // PRESET state tests
        {
            action: { type: ACTION.CHANGE_TAB },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "last-7-days" },
                isDirty: false,
                now,
                state: STATE.PRESET,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "last-7-days" },
                isDirty: false,
                now,
                state: STATE.CUSTOM,
            },
            title: "CHANGE_TAB from PRESET moves to CUSTOM state",
        },
        {
            action: {
                newValue: { timeFrame: "last-30-days" },
                timezone,
                type: ACTION.CHANGE_CURRENT_VALUE,
            },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "last-7-days" },
                isDirty: false,
                now,
                state: STATE.PRESET,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "last-30-days" },
                isDirty: true,
                now: expect.any(Object),
                state: STATE.PRESET,
            },
            title: "CHANGE_CURRENT_VALUE in PRESET updates timeFrame value and sets isDirty",
        },
        {
            action: { type: ACTION.SUBMIT },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [dayjs("2023-01-01"), dayjs("2023-01-07")],
                currentTimeFrameValue: { timeFrame: "last-30-days" },
                isDirty: true,
                now,
                state: STATE.PRESET,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "last-30-days" },
                isDirty: false,
                now,
                state: STATE.PRESET,
            },
            title: "SUBMIT in PRESET clears custom values",
        },
        {
            action: {
                initialValue: { timeFrame: "last-7-days" },
                timezone,
                type: ACTION.CANCEL,
            },
            initialState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "last-30-days" },
                isDirty: true,
                now,
                state: STATE.PRESET,
            },
            nextState: {
                availableTabs: [STATE.CUSTOM, STATE.PRESET],
                currentCustomValue: [null, null],
                currentTimeFrameValue: { timeFrame: "last-7-days" },
                isDirty: false,
                now: expect.any(Object),
                state: STATE.PRESET,
            },
            title: "CANCEL in PRESET returns to initial state",
        },
    ];
    describe("reducer", () => {
        for (const testCase of tests) {
            it(`${testCase.title}`, () => {
                const actualState = reducer(testCase.initialState, testCase.action);
                expect(actualState).toEqual(testCase.nextState);
            });
        }
    });
    describe("createInitialState", () => {
        it("creates PRESET state with timeFrame value", () => {
            const state = createInitialState({
                timezone: "UTC",
                value: { timeFrame: "last-7-days" },
            });
            expect(state.state).toBe(STATE.PRESET);
            expect(state.currentTimeFrameValue).toEqual({ timeFrame: "last-7-days" });
            expect(state.isDirty).toBe(false);
        });
        it("creates CUSTOM state with date range values", () => {
            const from = dayjs("2023-01-01").valueOf();
            const to = dayjs("2023-01-07").valueOf();
            const state = createInitialState({
                timezone: "UTC",
                value: { from, to },
            });
            expect(state.state).toBe(STATE.CUSTOM);
            expect(state.currentCustomValue[0]?.valueOf()).toBe(from);
            expect(state.currentCustomValue[1]?.valueOf()).toBe(to);
            expect(state.isDirty).toBe(false);
        });
        it("defaults to first tab when no value is provided", () => {
            const state = createInitialState({
                tabs: ["preset", "custom"],
                timezone: "UTC",
            });
            expect(state.state).toBe(STATE.PRESET);
            expect(state.availableTabs).toEqual([STATE.PRESET, STATE.CUSTOM]);
            expect(state.isDirty).toBe(false);
        });
    });
});
